# -*- coding: utf-8 -*-
import threading
import time
import traceback

from elementum.dialog_select import DialogSelect
from elementum.logger import log


_lock = threading.RLock()
_pending_open = []
_pending_update = []
_installed = False
_original_show = None
_original_update = None


def _queue_unique(queue, window):
    with _lock:
        if window not in queue:
            queue.append(window)


def _managed_show(window):
    if getattr(window, 'web_mode', False):
        return _original_show(window)

    with window.lock:
        window.remote_kodi_mode = False
        window.progressive_gui_managed = True
        window.progressive_gui_opened = False
        window.initialized = False
        window.finished = False
        window.web_updated_at = time.time()

    _queue_unique(_pending_open, window)
    log.info(
        'Progressive GUI open queued: session=%s items=%d'
        % (window.web_session_id, len(window.items))
    )
    return None


def _managed_update(window, items):
    if getattr(window, 'web_mode', False):
        return _original_update(window, items)

    if not getattr(window, 'progressive_gui_managed', False):
        return _original_update(window, items)

    with window.lock:
        window.items = list(items)
        window.web_updated_at = time.time()

    _queue_unique(_pending_update, window)
    log.info(
        'Progressive GUI update queued: session=%s items=%d initialized=%s'
        % (
            window.web_session_id,
            len(window.items),
            window.initialized,
        )
    )
    return None


def install_progressive_gui_dispatcher():
    global _installed, _original_show, _original_update

    with _lock:
        if _installed:
            return

        _original_show = DialogSelect.show
        _original_update = DialogSelect.updateItems
        DialogSelect.show = _managed_show
        DialogSelect.updateItems = _managed_update
        _installed = True

    log.info('Progressive GUI dispatcher installed')


def _open_window(window):
    with window.lock:
        if window.finished or window.progressive_gui_opened:
            return

    try:
        log.info(
            'Progressive GUI opening on service thread: session=%s items=%d thread=%s'
            % (
                window.web_session_id,
                len(window.items),
                threading.current_thread().name,
            )
        )

        # Bypass DialogSelect.show(), which is monkey-patched above, and call
        # the real WindowXMLDialog implementation from Kodi's service thread.
        super(DialogSelect, window).show()

        with window.lock:
            window.progressive_gui_opened = True
    except Exception as exc:
        with window.lock:
            window.finished = True
        log.error(
            'Progressive GUI open failed: session=%s error=%s'
            % (window.web_session_id, repr(exc))
        )
        for line in traceback.format_exc().splitlines():
            log.error(line)


def _apply_latest_items(window):
    try:
        with window.lock:
            if window.finished or not window.initialized:
                return

            list_control = window.getControl(32503)
            selected = list_control.getSelectedPosition()
            list_control.reset()
            window.count = 0

            for item in window.items:
                window._addItem(item)

            if window.count:
                list_control.selectItem(
                    min(max(selected, 0), window.count - 1)
                )

            window._log_control_size('service-update')
    except Exception as exc:
        log.error(
            'Progressive GUI update failed: session=%s error=%s'
            % (window.web_session_id, repr(exc))
        )
        for line in traceback.format_exc().splitlines():
            log.error(line)


def process_pending_progressive_gui():
    with _lock:
        opens = list(_pending_open)
        updates = list(_pending_update)
        del _pending_open[:]
        del _pending_update[:]

    for window in opens:
        _open_window(window)

    for window in updates:
        _apply_latest_items(window)
